"""Generate per-derivation JSON chains under ``AutoGenerated/derivations/``.

Each derivation chain is a self-contained JSON describing the symbolic
proof for one physics sector — gauge unification, cosmology evolution,
neutrino mixing, fermion masses, etc. — together with Wolfram Alpha
queries for offline verification.

This generator has two modes:

* **cached** (default) — copy the bundled snapshots from
  ``metaphysica/data/derivations/<name>.json`` into
  ``<out_dir>/AutoGenerated/derivations/<name>.json``. Cheap, fully
  deterministic, suitable for CI.
* **live Wolfram** — set ``METAPHYSICA_USE_WOLFRAM=1`` to attempt
  re-running the original derivation modules
  (``simulations.derivations.*_derivations``) which call out to Wolfram
  via the Wolfram Cloud / kernel. Only enable this on a machine with
  ``wolframclient`` configured and a Wolfram Engine licence.

The cached path is the supported default — the live path is opt-in and
intentionally tolerant of failures: any chain that doesn't regenerate
falls back to the bundled snapshot.
"""
from __future__ import annotations

import json
import os
import shutil
import sys
from importlib.resources import files
from pathlib import Path
from typing import List, Tuple

from metaphysica.generators._common import autogen_dir


# Live regeneration is opt-in: most installs won't have wolframclient set up.
_USE_WOLFRAM_ENV = "METAPHYSICA_USE_WOLFRAM"


def _bundled_chain_names() -> List[str]:
    """List every chain JSON bundled under metaphysica/data/derivations/."""
    try:
        root = files("metaphysica.data.derivations")
    except (ModuleNotFoundError, FileNotFoundError):
        return []
    names: List[str] = []
    for entry in root.iterdir():
        nm = entry.name
        if nm.endswith(".json"):
            names.append(nm)
    return sorted(names)


def _copy_cached_chain(name: str, dst_dir: Path) -> bool:
    """Copy one bundled chain JSON into *dst_dir*. Returns True on success."""
    try:
        src = files("metaphysica.data.derivations") / name
        if not src.is_file():
            return False
        payload = json.loads(src.read_text(encoding="utf-8"))
    except Exception:
        return False
    out_path = dst_dir / name
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(
        json.dumps(payload, indent=2, ensure_ascii=False, default=str),
        encoding="utf-8",
    )
    return True


def _try_live_wolfram_regen(dst_dir: Path) -> Tuple[int, List[str]]:
    """Attempt to re-run the original derivation modules against Wolfram.

    The legacy modules live under ``simulations.derivations.<sector>_derivations``
    (not part of the metaphysica wheel). If they're importable in the current
    environment, call their ``export_to_json`` entry point with our target
    directory; otherwise fall through.

    Returns ``(n_regenerated, failures)``. Any failure here is *not* fatal —
    the cached snapshot for that chain will be used instead.
    """
    sectors = [
        ("baryogenesis", "baryogenesis_chain.json"),
        ("cosmology",    "cosmology_chain.json"),
        ("dark_matter",  "dark_matter_chain.json"),
        ("fermion",      "fermion_chain.json"),
        ("g2_geometry",  "g2_geometry_chain.json"),
        ("gauge",        "gauge_chain.json"),
        ("higgs",        "higgs_chain.json"),
        ("master_action", "master_action_chain.json"),
        ("neutrino",     "neutrino_chain.json"),
        ("quantum_bio",  "quantum_bio_chain.json"),
        ("vacuum_stability", "vacuum_stability_chain.json"),
    ]
    regenerated = 0
    failures: List[str] = []
    for sector, fname in sectors:
        mod_path = f"simulations.derivations.{sector}_derivations"
        try:
            import importlib
            mod = importlib.import_module(mod_path)
            export_fn = getattr(mod, "export_to_json", None)
            if export_fn is None:
                failures.append(f"{sector}: no export_to_json()")
                continue
            export_fn(str(dst_dir / fname))
            regenerated += 1
        except Exception as exc:
            failures.append(
                f"{sector}: {type(exc).__name__}: {exc}"
            )
    return regenerated, failures


def generate() -> Tuple[int, List[str]]:
    """Emit one JSON per derivation chain into AutoGenerated/derivations/.

    Returns ``(n_written, failures)``.
    """
    dst_dir = autogen_dir() / "derivations"
    dst_dir.mkdir(parents=True, exist_ok=True)

    bundled = _bundled_chain_names()
    if not bundled:
        return 0, ["no bundled derivation chains found under metaphysica.data.derivations"]

    use_wolfram = os.environ.get(_USE_WOLFRAM_ENV, "").strip() not in ("", "0", "false", "False")

    regenerated: set[str] = set()
    failures: List[str] = []

    if use_wolfram:
        n_regen, regen_failures = _try_live_wolfram_regen(dst_dir)
        failures.extend(regen_failures)
        if n_regen > 0:
            print(f"  Live Wolfram regeneration succeeded for {n_regen} chain(s).")
        # Anything that successfully wrote a file is already on disk.
        for name in bundled:
            if (dst_dir / name).is_file():
                regenerated.add(name)

    # Cache-copy every chain that didn't get a live update.
    written = 0
    for name in bundled:
        if name in regenerated:
            written += 1
            continue
        if _copy_cached_chain(name, dst_dir):
            written += 1
        else:
            failures.append(f"{name}: failed to copy bundled snapshot")

    return written, failures


def main() -> int:
    print("=== Generate AutoGenerated/derivations/ chains ===")
    mode = "live-wolfram" if os.environ.get(_USE_WOLFRAM_ENV) else "cached"
    print(f"  Mode: {mode}  (set {_USE_WOLFRAM_ENV}=1 to attempt live regeneration)")
    n, failures = generate()
    print(f"Wrote {n} derivation chain(s) into AutoGenerated/derivations/.")
    if failures:
        print(f"Notes / failures ({len(failures)}):")
        for f in failures:
            print(f"  {f}")
        # Cached-copy failures are real errors; live-Wolfram skips are not.
        hard_failures = [f for f in failures if "failed to copy" in f or "no bundled" in f]
        if hard_failures:
            return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
